window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["binance"]={html:"<div class=\"own-binance\">\n  <header class=\"bn-nav\">\n    <a class=\"bn-brand\" href=\"#bn-top\">\n      <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 2 5 5.5 8.5 9 12 5.5 15.5 9 19 5.5 12 2Z\"/><path d=\"M8.5 12 12 8.5 15.5 12 12 15.5 8.5 12Z\"/><path d=\"M12 18.5 5 22l3.5-3.5L12 22l3.5-3.5L19 22l-7-3.5Z\"/></svg>\n      <span>Northwind</span>\n    </a>\n    <nav class=\"bn-menu\" aria-label=\"Primary\">\n      <a href=\"#bn-trust\">Overview</a>\n      <a href=\"#bn-markets\">Markets</a>\n      <a href=\"#bn-table\">Regions</a>\n      <a href=\"#bn-safe\">Guardrails</a>\n      <a href=\"#bn-steps\">Pricing</a>\n    </nav>\n    <div class=\"bn-nav-right\">\n      <button class=\"bn-icon\" type=\"button\" aria-label=\"Language\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><path d=\"M4 12h16M12 4c2.5 3 2.5 13 0 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/></svg></button>\n      <a class=\"bn-navlink\" href=\"#\">Log in</a>\n      <a class=\"bn-btn bn-btn-primary\" href=\"#\">Start free trial</a>\n    </div>\n  </header>\n\n  <main id=\"bn-top\">\n    <section class=\"bn-hero\" aria-labelledby=\"bn-h1\">\n      <div class=\"bn-hero-copy\">\n        <h1 id=\"bn-h1\" class=\"bn-h1\">316,258 operations rows resolved daily</h1>\n        <p class=\"bn-hero-sub\">One governed model for every region, line, and shift. Throughput, yield, and cost settle against the same source — read at a glance, acted on in the same hour.</p>\n        <form class=\"bn-search\" role=\"search\" onsubmit=\"return false\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"m20 20-4-4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg>\n          <input type=\"search\" placeholder=\"Search regions and boards\" aria-label=\"Search regions and boards\" autocomplete=\"off\">\n        </form>\n      </div>\n      <aside class=\"bn-markets\" aria-label=\"Markets snapshot\">\n        <div class=\"bn-markets-tabs\" id=\"bnMarketTabs\" role=\"tablist\" aria-label=\"Market filter\">\n          <button class=\"bn-mtab on\" type=\"button\" role=\"tab\" data-m=\"popular\" aria-selected=\"true\">Popular</button>\n          <button class=\"bn-mtab\" type=\"button\" role=\"tab\" data-m=\"gainers\" aria-selected=\"false\">Top gainers</button>\n          <button class=\"bn-mtab\" type=\"button\" role=\"tab\" data-m=\"new\" aria-selected=\"false\">New listing</button>\n        </div>\n        <div class=\"bn-markets-head\"><span>Region</span><span>Throughput</span><span>24h</span><span></span></div>\n        <div class=\"bn-markets-body\" id=\"bnMarkets\"></div>\n      </aside>\n    </section>\n\n    <section class=\"bn-trust\" aria-label=\"Trust badges\">\n      <div class=\"bn-badge\"><b>No.1</b><span>Ops model uptime</span></div>\n      <div class=\"bn-badge\"><b>No.1</b><span>Region coverage</span></div>\n      <div class=\"bn-badge\"><b>24/7</b><span>Ops desk support</span></div>\n      <div class=\"bn-badge\"><b>99.98%</b><span>Refresh reliability</span></div>\n    </section>\n\n    <section id=\"bn-markets\" class=\"bn-band\" aria-labelledby=\"bn-band-h\">\n      <div class=\"bn-band-head\">\n        <p class=\"bn-eyebrow\">Live now</p>\n        <h2 id=\"bn-band-h\" class=\"bn-h2\">Every region's real number, ticking</h2>\n      </div>\n      <div class=\"bn-cards\">\n        <article class=\"bn-card bn-card-2x\">\n          <p class=\"bn-card-label\">Network throughput</p>\n          <p class=\"bn-num\" id=\"bnThroughput\">412,908</p>\n          <p class=\"bn-up\">▲ 2.1% vs yesterday</p>\n          <div class=\"bn-bars\" id=\"bnBars\" aria-hidden=\"true\"></div>\n        </article>\n        <article class=\"bn-card\">\n          <p class=\"bn-card-label\">Line yield</p>\n          <p class=\"bn-num bn-num-sm\">94.6%</p>\n          <div class=\"bn-gauge\"><span style=\"width:94.6%\"></span></div>\n        </article>\n        <article class=\"bn-card\">\n          <p class=\"bn-card-label\">Cost / unit</p>\n          <p class=\"bn-num bn-num-sm\">$2.41</p>\n          <p class=\"bn-down\">▼ 8.3% this quarter</p>\n        </article>\n      </div>\n    </section>\n\n    <section id=\"bn-table\" class=\"bn-band\" aria-labelledby=\"bn-table-h\">\n      <div class=\"bn-band-head\">\n        <p class=\"bn-eyebrow\">Markets</p>\n        <h2 id=\"bn-table-h\" class=\"bn-h2\">Regional performance table</h2>\n      </div>\n      <div class=\"bn-table\" role=\"table\" aria-label=\"Regional performance\">\n        <div class=\"bn-tr bn-th\" role=\"row\"><span>Region</span><span>Throughput</span><span>24h change</span><span>Volume</span><span></span></div>\n        <div id=\"bnTableBody\"></div>\n      </div>\n    </section>\n\n    <section id=\"bn-safe\" class=\"bn-safe\" aria-labelledby=\"bn-safe-h\">\n      <h2 id=\"bn-safe-h\" class=\"bn-safe-h\">Guardrails are always on</h2>\n      <div class=\"bn-safe-stats\">\n        <div class=\"bn-safe-stat\"><b>429,423</b><span>units recovered</span></div>\n        <div class=\"bn-safe-stat\"><b>15,000</b><span>lines monitored</span></div>\n        <div class=\"bn-safe-stat\"><b>7,488</b><span>shifts assisted</span></div>\n      </div>\n    </section>\n\n    <section id=\"bn-steps\" class=\"bn-band\" aria-labelledby=\"bn-steps-h\">\n      <div class=\"bn-band-head\">\n        <p class=\"bn-eyebrow\">Onboarding</p>\n        <h2 id=\"bn-steps-h\" class=\"bn-h2\">Start in three steps</h2>\n      </div>\n      <div class=\"bn-steps\">\n        <article class=\"bn-step\"><span class=\"bn-step-n\">1</span><h3>Connect a region</h3><p>Point Northwind at one site and it resolves the first board in under an hour.</p></article>\n        <article class=\"bn-step\"><span class=\"bn-step-n\">2</span><h3>Set the goal</h3><p>Name the throughput or yield goal; the guardrail marks the 100%-of-goal line.</p></article>\n        <article class=\"bn-step\"><span class=\"bn-step-n\">3</span><h3>Share the digest</h3><p>Every shift handover gets the same number in the ops desk inbox.</p></article>\n      </div>\n    </section>\n\n    <section class=\"bn-faq\" aria-labelledby=\"bn-faq-h\">\n      <h2 id=\"bn-faq-h\" class=\"bn-h2\">Questions from the floor</h2>\n      <div class=\"bn-faq-list\" id=\"bnFaq\"></div>\n    </section>\n\n    <section class=\"bn-cta\" aria-labelledby=\"bn-cta-h\">\n      <h2 id=\"bn-cta-h\" class=\"bn-cta-h\">Secure, governed operations on Northwind</h2>\n      <a class=\"bn-btn bn-btn-primary bn-btn-pill\" href=\"#\">Get started</a>\n    </section>\n  </main>\n\n  <footer class=\"bn-footer\">\n    <div class=\"bn-foot-cols\">\n      <div class=\"bn-foot-col\"><h3>Community</h3><a href=\"#\">Ops forum</a><a href=\"#\">Changelog</a><a href=\"#\">Status</a></div>\n      <div class=\"bn-foot-col\"><h3>Products</h3><a href=\"#\">Boards</a><a href=\"#\">Guardrails</a><a href=\"#\">Digest</a></div>\n      <div class=\"bn-foot-col\"><h3>Service</h3><a href=\"#\">Ops desk</a><a href=\"#\">Onboarding</a><a href=\"#\">Contact</a></div>\n      <div class=\"bn-foot-col\"><h3>Learn</h3><a href=\"#\">Guides</a><a href=\"#\">API docs</a><a href=\"#\">Security</a></div>\n    </div>\n    <div class=\"bn-legal\">\n      <span>© 2026 Northwind Analytics — sample data, showcase only</span>\n      <span class=\"bn-legal-links\"><a href=\"#\">Terms</a><a href=\"#\">Privacy</a><a href=\"#\">Cookies</a></span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in the Binance design language, for showcase.html ══════════\n   Deep near-black canvas, one Binance-Yellow voltage, BinanceNova/Plex type\n   (JetBrains Mono for numbers as the Plex substitute), flat color-block cards,\n   trading green/red as text-only signals, and the deliberate light footer that\n   closes a dark page. */\n\n.own-binance {\n  --primary: #fcd535;\n  --primary-active: #f0b90b;\n  --primary-disabled: #3a3a1f;\n  --ink: #181a20;\n  --body: #eaecef;\n  --body-on-light: #181a20;\n  --muted: #707a8a;\n  --muted-strong: #929aa5;\n  --hairline-on-light: #eaecef;\n  --hairline-on-dark: #2b3139;\n  --border-strong: #cdd1d6;\n  --canvas-light: #ffffff;\n  --canvas-dark: #0b0e11;\n  --surface-card-dark: #1e2329;\n  --surface-elevated-dark: #2b3139;\n  --on-primary: #181a20;\n  --on-dark: #ffffff;\n  --trading-up: #0ecb81;\n  --trading-down: #f6465d;\n  --accent-turquoise: #2dbdb6;\n  --info: #3b82f6;\n  --r-xs: 2px;\n  --r-sm: 4px;\n  --r-md: 6px;\n  --r-lg: 8px;\n  --r-xl: 12px;\n  --r-pill: 9999px;\n  --font: 'Inter', 'BinanceNova', -apple-system, BlinkMacSystemFont, sans-serif;\n  --font-num: 'JetBrains Mono', 'IBM Plex Sans', 'BinancePlex', sans-serif;\n  --gut: clamp(20px, 4.5cqi, 72px);\n  --section: clamp(52px, 6.4cqi, 80px);\n\n  position: relative;\n  background: var(--canvas-dark);\n  color: var(--body);\n  font-family: var(--font);\n  font-size: 14px;\n  line-height: 1.5;\n  text-align: left;\n  border-radius: 13px;\n  overflow-x: clip;\n}\n.own-binance *, .own-binance *::before, .own-binance *::after { box-sizing: border-box; }\n.own-binance a { color: inherit; text-decoration: none; }\n.own-binance button { font: inherit; cursor: pointer; }\n.own-binance :focus-visible { outline: 2px solid var(--info); outline-offset: 2px; border-radius: 4px; }\n\n/* ── nav (64px) ───────────────────────────────────────────────────────────── */\n.own-binance .bn-nav { position: sticky; top: 68px; z-index: 30; display: flex; align-items: center; gap: 26px; height: 64px; padding: 0 var(--gut); background: var(--canvas-dark); border-bottom: 1px solid var(--hairline-on-dark); }\n.own-binance .bn-brand { display: flex; align-items: center; gap: 8px; color: var(--primary); font-family: var(--font); font-size: 20px; font-weight: 700; letter-spacing: -.5px; }\n.own-binance .bn-brand svg { width: 24px; height: 24px; fill: var(--primary); }\n.own-binance .bn-menu { display: flex; gap: 22px; font-size: 14px; font-weight: 500; color: var(--body); }\n.own-binance .bn-menu a:hover { color: var(--primary); }\n.own-binance .bn-nav-right { display: flex; align-items: center; gap: 14px; margin-left: auto; }\n.own-binance .bn-icon { display: grid; place-items: center; width: 34px; height: 34px; border: 0; border-radius: 50%; background: transparent; color: var(--body); }\n.own-binance .bn-icon:hover { background: var(--surface-card-dark); }\n.own-binance .bn-icon svg { width: 18px; height: 18px; }\n.own-binance .bn-navlink { font-size: 14px; font-weight: 500; }\n.own-binance .bn-navlink:hover { color: var(--primary); }\n\n/* ── buttons ──────────────────────────────────────────────────────────────── */\n.own-binance .bn-btn { display: inline-flex; align-items: center; justify-content: center; height: 40px; padding: 0 24px; border: 1px solid transparent; border-radius: var(--r-md); font-size: 14px; font-weight: 600; }\n.own-binance .bn-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-binance .bn-btn-primary:hover { background: var(--primary-active); }\n.own-binance .bn-btn-pill { border-radius: var(--r-pill); height: 48px; padding: 0 32px; }\n\n/* ── hero (dark band) ─────────────────────────────────────────────────────── */\n.own-binance .bn-hero { display: grid; grid-template-columns: 1.05fr .95fr; gap: 40px; align-items: center; max-width: 1280px; margin: 0 auto; padding: var(--section) var(--gut); }\n.own-binance .bn-h1 { font-family: var(--font); font-size: clamp(36px, 5.6cqi, 64px); font-weight: 700; line-height: 1.1; letter-spacing: -1px; color: var(--on-dark); }\n.own-binance .bn-hero-sub { font-size: 14px; color: var(--body); max-width: 52ch; margin: 20px 0 26px; }\n.own-binance .bn-search { display: flex; align-items: center; gap: 10px; max-width: 420px; height: 40px; padding: 0 16px; border-radius: var(--r-lg); background: var(--surface-card-dark); }\n.own-binance .bn-search svg { width: 17px; height: 17px; color: var(--muted); flex: none; }\n.own-binance .bn-search input { width: 100%; border: 0; background: none; color: var(--on-dark); font: inherit; font-size: 14px; }\n.own-binance .bn-search input::placeholder { color: var(--muted); }\n.own-binance .bn-search input:focus { outline: none; }\n.own-binance .bn-search:focus-within { box-shadow: 0 0 0 2px rgba(59, 130, 246, .5); }\n\n/* markets snapshot card */\n.own-binance .bn-markets { border-radius: var(--r-xl); background: var(--surface-card-dark); padding: 24px; }\n.own-binance .bn-markets-tabs { display: flex; gap: 6px; margin-bottom: 14px; }\n.own-binance .bn-mtab { padding: 6px 12px; border: 0; border-radius: var(--r-sm); background: transparent; color: var(--muted); font-size: 13px; font-weight: 500; }\n.own-binance .bn-mtab:hover { color: var(--body); }\n.own-binance .bn-mtab.on { background: var(--primary); color: var(--on-primary); font-weight: 600; }\n.own-binance .bn-markets-head, .own-binance .bn-mrow { display: grid; grid-template-columns: 1.2fr 1fr .8fr 20px; gap: 12px; align-items: center; }\n.own-binance .bn-markets-head { padding: 6px 0 10px; font-size: 12px; font-weight: 500; color: var(--muted); border-bottom: 1px solid var(--hairline-on-dark); }\n.own-binance .bn-mrow { padding: 12px 0; border-bottom: 1px solid var(--hairline-on-dark); }\n.own-binance .bn-mrow:last-child { border-bottom: 0; }\n.own-binance .bn-mcoin { display: flex; align-items: center; gap: 10px; font-size: 14px; font-weight: 500; color: var(--on-dark); }\n.own-binance .bn-mcoin i { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; background: var(--surface-elevated-dark); font-style: normal; font-family: var(--font-num); font-size: 11px; color: var(--primary); }\n.own-binance .bn-mprice { font-family: var(--font-num); font-size: 16px; font-weight: 500; color: var(--on-dark); }\n.own-binance .bn-mchg { font-family: var(--font-num); font-size: 14px; font-weight: 500; }\n.own-binance .bn-up-t { color: var(--trading-up); }\n.own-binance .bn-down-t { color: var(--trading-down); }\n.own-binance .bn-mgo { color: var(--muted); text-align: right; }\n\n/* ── trust badges ─────────────────────────────────────────────────────────── */\n.own-binance .bn-trust { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; max-width: 1280px; margin: 0 auto; padding: 0 var(--gut) var(--section); }\n.own-binance .bn-badge { display: grid; gap: 4px; padding: 16px 20px; border-radius: var(--r-lg); background: var(--surface-card-dark); }\n.own-binance .bn-badge b { font-family: var(--font-num); font-size: 20px; font-weight: 700; color: var(--primary); }\n.own-binance .bn-badge span { font-size: 14px; font-weight: 600; color: var(--on-dark); }\n\n/* ── band ─────────────────────────────────────────────────────────────────── */\n.own-binance .bn-band { max-width: 1280px; margin: 0 auto; padding: 0 var(--gut) var(--section); }\n.own-binance .bn-band-head { margin-bottom: 28px; }\n.own-binance .bn-eyebrow { font-size: 12px; font-weight: 500; color: var(--primary); margin-bottom: 8px; }\n.own-binance .bn-h2 { font-family: var(--font); font-size: clamp(28px, 3.6cqi, 40px); font-weight: 600; line-height: 1.15; letter-spacing: -.3px; color: var(--on-dark); }\n.own-binance .bn-cards { display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 16px; align-items: stretch; }\n.own-binance .bn-card { display: grid; gap: 8px; align-content: start; padding: 24px; border-radius: var(--r-xl); background: var(--surface-card-dark); }\n.own-binance .bn-card-label { font-size: 12px; font-weight: 500; color: var(--muted); }\n.own-binance .bn-num { font-family: var(--font-num); font-size: clamp(30px, 4cqi, 40px); font-weight: 700; line-height: 1.1; letter-spacing: -.3px; color: var(--primary); }\n.own-binance .bn-num-sm { font-size: 28px; }\n.own-binance .bn-up { font-family: var(--font-num); font-size: 14px; font-weight: 500; color: var(--trading-up); }\n.own-binance .bn-down { font-family: var(--font-num); font-size: 14px; font-weight: 500; color: var(--trading-down); }\n.own-binance .bn-bars { display: flex; align-items: flex-end; gap: 5px; height: 86px; margin-top: 8px; }\n.own-binance .bn-bars span { flex: 1; border-radius: 3px 3px 0 0; background: var(--trading-up); opacity: .55; }\n.own-binance .bn-bars span.dn { background: var(--trading-down); }\n.own-binance .bn-gauge { height: 8px; border-radius: 4px; background: var(--surface-elevated-dark); overflow: hidden; margin-top: 10px; }\n.own-binance .bn-gauge span { display: block; height: 100%; background: var(--trading-up); border-radius: 4px; }\n\n/* ── markets table ────────────────────────────────────────────────────────── */\n.own-binance .bn-table { border-radius: var(--r-xl); background: var(--surface-card-dark); padding: 24px; }\n.own-binance .bn-tr { display: grid; grid-template-columns: 1.3fr 1fr 1fr 1fr 90px; gap: 12px; align-items: center; }\n.own-binance .bn-th { padding-bottom: 12px; border-bottom: 1px solid var(--hairline-on-dark); font-size: 12px; font-weight: 500; color: var(--muted); }\n.own-binance .bn-trow { padding: 12px 0; border-bottom: 1px solid var(--hairline-on-dark); }\n.own-binance .bn-trow:last-child { border-bottom: 0; }\n.own-binance .bn-trow .bn-td { font-family: var(--font-num); font-size: 16px; font-weight: 500; color: var(--on-dark); }\n.own-binance .bn-trow .bn-td-name { display: flex; align-items: center; gap: 10px; font-family: var(--font); font-size: 14px; font-weight: 500; color: var(--on-dark); }\n.own-binance .bn-trow .bn-td-name i { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; background: var(--surface-elevated-dark); font-style: normal; font-family: var(--font-num); font-size: 11px; color: var(--primary); }\n.own-binance .bn-sub { display: inline-flex; align-items: center; justify-content: center; height: 28px; padding: 0 16px; border: 0; border-radius: var(--r-sm); background: var(--primary); color: var(--on-primary); font-size: 13px; font-weight: 600; }\n\n/* ── funds-are-safe band ──────────────────────────────────────────────────── */\n.own-binance .bn-safe { max-width: 1280px; margin: 0 auto; padding: 0 var(--gut) var(--section); }\n.own-binance .bn-safe-h { font-family: var(--font); font-size: clamp(30px, 4.4cqi, 48px); font-weight: 700; line-height: 1.1; letter-spacing: -.5px; color: var(--primary); }\n.own-binance .bn-safe-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 26px; }\n.own-binance .bn-safe-stat { display: grid; gap: 4px; }\n.own-binance .bn-safe-stat b { font-family: var(--font-num); font-size: clamp(28px, 4cqi, 40px); font-weight: 700; line-height: 1.1; color: var(--primary); }\n.own-binance .bn-safe-stat span { font-size: 14px; color: var(--body); }\n\n/* ── steps ────────────────────────────────────────────────────────────────── */\n.own-binance .bn-steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }\n.own-binance .bn-step { display: grid; gap: 10px; padding: 24px; border-radius: var(--r-lg); background: var(--canvas-light); color: var(--ink); }\n.own-binance .bn-step-n { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: var(--primary); color: var(--on-primary); font-family: var(--font-num); font-size: 15px; font-weight: 700; }\n.own-binance .bn-step h3 { font-size: 16px; font-weight: 600; }\n.own-binance .bn-step p { font-size: 14px; color: #5e6673; }\n\n/* ── faq ──────────────────────────────────────────────────────────────────── */\n.own-binance .bn-faq { max-width: 900px; margin: 0 auto; padding: 0 var(--gut) var(--section); }\n.own-binance .bn-faq-list { margin-top: 20px; border-top: 1px solid var(--hairline-on-dark); }\n.own-binance .bn-faq-row { border-bottom: 1px solid var(--hairline-on-dark); }\n.own-binance .bn-faq-q { display: flex; align-items: center; justify-content: space-between; gap: 16px; width: 100%; padding: 20px 0; border: 0; background: transparent; color: var(--on-dark); font-size: 16px; font-weight: 600; text-align: left; }\n.own-binance .bn-faq-q svg { width: 18px; height: 18px; color: var(--primary); transition: transform .25s ease; flex: none; }\n.own-binance .bn-faq-row.open .bn-faq-q svg { transform: rotate(180deg); }\n.own-binance .bn-faq-a { overflow: hidden; max-height: 0; transition: max-height .3s ease; }\n.own-binance .bn-faq-row.open .bn-faq-a { max-height: 240px; }\n.own-binance .bn-faq-a p { padding: 0 0 20px; font-size: 14px; color: var(--body); max-width: 74ch; }\n\n/* ── CTA band ─────────────────────────────────────────────────────────────── */\n.own-binance .bn-cta { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; max-width: 1280px; margin: 0 auto var(--section); padding: 48px; border-radius: var(--r-xl); background: var(--surface-card-dark); }\n.own-binance .bn-cta-h { font-family: var(--font); font-size: clamp(24px, 3.2cqi, 32px); font-weight: 600; line-height: 1.2; color: var(--on-dark); max-width: 24ch; }\n\n/* ── footer (light, closes the dark page) ─────────────────────────────────── */\n.own-binance .bn-footer { background: #fafafa; color: var(--body-on-light); padding: 64px var(--gut) 32px; }\n.own-binance .bn-foot-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; max-width: 1280px; margin: 0 auto; }\n.own-binance .bn-foot-col { display: grid; gap: 10px; align-content: start; }\n.own-binance .bn-foot-col h3 { font-size: 14px; font-weight: 600; margin-bottom: 4px; }\n.own-binance .bn-foot-col a { font-size: 14px; color: #5e6673; }\n.own-binance .bn-foot-col a:hover { color: var(--primary-active); }\n.own-binance .bn-legal { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; max-width: 1280px; margin: 40px auto 0; padding-top: 20px; border-top: 1px solid var(--hairline-on-light); font-size: 13px; color: #5e6673; }\n.own-binance .bn-legal-links { display: inline-flex; gap: 18px; }\n.own-binance .bn-legal-links a:hover { color: var(--primary-active); }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-binance .bn-menu { display: none; }\n  .own-binance .bn-hero { grid-template-columns: 1fr; gap: 28px; }\n  .own-binance .bn-trust { grid-template-columns: repeat(2, 1fr); }\n  .own-binance .bn-cards { grid-template-columns: 1fr 1fr; }\n  .own-binance .bn-card-2x { grid-column: span 2; }\n  .own-binance .bn-steps { grid-template-columns: 1fr; }\n  .own-binance .bn-foot-cols { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 760px) {\n  .own-binance .bn-nav { top: 0; height: 60px; padding: 0 16px; gap: 12px; }\n  .own-binance .bn-nav-right .bn-navlink, .own-binance .bn-icon { display: none; }\n  .own-binance .bn-hero { padding: 44px 16px; }\n  .own-binance .bn-trust { padding: 0 16px 48px; }\n  .own-binance .bn-band, .own-binance .bn-safe, .own-binance .bn-faq { padding: 0 16px 48px; }\n  .own-binance .bn-cards { grid-template-columns: 1fr; }\n  .own-binance .bn-card-2x { grid-column: auto; }\n  .own-binance .bn-tr { grid-template-columns: 1.4fr 1fr 1fr; }\n  .own-binance .bn-tr > *:nth-child(4), .own-binance .bn-tr > *:nth-child(5) { display: none; }\n  .own-binance .bn-safe-stats { grid-template-columns: 1fr; }\n  .own-binance .bn-cta { margin: 0 16px 48px; padding: 28px 20px; flex-direction: column; align-items: flex-start; }\n  .own-binance .bn-footer { padding: 48px 16px 24px; }\n}\n@container frame (max-width: 430px) {\n  .own-binance .bn-foot-cols { grid-template-columns: 1fr; }\n  .own-binance .bn-cards { grid-template-columns: 1fr; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-binance *, .own-binance *::before, .own-binance *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — Binance-language trading-desk boards for showcase.html ═════
   Registers window.OWN_LAYOUTS['binance'].init(root). Renders the markets
   snapshot, region table, throughput bars, and FAQ accordion, and returns a
   cleanup that detaches every listener and cancels any running rAF. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var MARKETS = [
    { sym: 'LUZ', name: 'Luzon', price: '412,908', pct: 2.1, pop: true, gain: true, fresh: false },
    { sym: 'BUS', name: 'Busan', price: '287,441', pct: 1.4, pop: true, gain: false, fresh: false },
    { sym: 'SIN', name: 'Singapore', price: '344,120', pct: -0.8, pop: true, gain: false, fresh: false },
    { sym: 'CEB', name: 'Cebu', price: '176,309', pct: 3.6, pop: false, gain: true, fresh: false },
    { sym: 'SYD', name: 'Sydney', price: '221,058', pct: -1.2, pop: false, gain: false, fresh: false },
    { sym: 'DVO', name: 'Davao', price: '133,776', pct: 4.9, pop: false, gain: true, fresh: false },
    { sym: 'RTM', name: 'Rotterdam', price: '198,204', pct: 0.6, pop: false, gain: false, fresh: true },
    { sym: 'MNL', name: 'Manila', price: '512,330', pct: 1.1, pop: false, gain: false, fresh: true }
  ];
  var BAR = [42, 58, 46, 71, 63, 80, 68, 88, 76, 94, 84, 61];
  var FAQ = [
    { q: 'Where does Northwind get its numbers?', a: 'One governed operations model resolves every region, line, and shift. Boards read from that model directly — there is no export step and no per-team mirror to reconcile.' },
    { q: 'How often do the boards refresh?', a: 'The model refreshes every fifteen minutes across all regions, so the number the night shift sees is the number the morning shift opens.' },
    { q: 'Can I run it on a single site?', a: 'Yes. The Team plan covers three boards and two regions with no card required for the first thirty days.' },
    { q: 'What are guardrails?', a: 'Guardrails compare each line against its named goal and flag drift in the same hour it appears — so a line is corrected before it reaches a customer.' }
  ];

  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function arrow(p) { return '<span class="' + (p >= 0 ? 'bn-up-t' : 'bn-down-t') + '">' + (p >= 0 ? '▲ ' : '▼ ') + Math.abs(p).toFixed(1) + '%</span>'; }

  function marketRow(m) {
    return '<div class="bn-mrow">'
      + '<span class="bn-mcoin"><i>' + esc(m.sym) + '</i>' + esc(m.name) + '</span>'
      + '<span class="bn-mprice">' + esc(m.price) + '</span>'
      + '<span class="bn-mchg ' + (m.pct >= 0 ? 'bn-up-t' : 'bn-down-t') + '">' + (m.pct >= 0 ? '+' : '') + m.pct.toFixed(1) + '%</span>'
      + '<span class="bn-mgo">›</span>'
      + '</div>';
  }

  OWN['binance'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var rafs = [];
      function on(el, type, fn, opt) { if (!el) return; opt = Object.assign({}, opt || {}); if (signal) opt.signal = signal; el.addEventListener(type, fn, opt); }
      function $(s) { return root.querySelector(s); }

      var markets = $('#bnMarkets');
      function renderMarkets(filter) {
        var list = MARKETS.filter(function (m) { return filter === 'popular' ? m.pop : filter === 'gainers' ? m.gain : m.fresh; });
        markets.innerHTML = (list.length ? list : MARKETS.slice(0, 4)).map(marketRow).join('');
      }
      renderMarkets('popular');
      on($('#bnMarketTabs'), 'click', function (e) {
        var b = e.target.closest('[data-m]'); if (!b) return;
        Array.prototype.forEach.call(root.querySelectorAll('#bnMarketTabs .bn-mtab'), function (t) {
          var on = t === b; t.classList.toggle('on', on); t.setAttribute('aria-selected', String(on));
        });
        renderMarkets(b.dataset.m);
      });

      var bars = $('#bnBars');
      if (bars) bars.innerHTML = BAR.map(function (h, i) {
        return '<span class="' + (i === 3 || i === 9 ? 'dn' : '') + '" style="height:' + h + '%"></span>';
      }).join('');

      var body = $('#bnTableBody');
      if (body) body.innerHTML = MARKETS.slice(0, 6).map(function (m) {
        var volume = (Number(String(m.price).replace(/,/g, '')) * 12.7 / 1000).toFixed(1);
        return '<div class="bn-tr bn-trow">'
          + '<span class="bn-td-name"><i>' + esc(m.sym) + '</i>' + esc(m.name) + '</span>'
          + '<span class="bn-td">' + esc(m.price) + '</span>'
          + '<span class="bn-td">' + arrow(m.pct) + '</span>'
          + '<span class="bn-td">' + volume + 'k</span>'
          + '<button class="bn-sub" type="button">Open</button>'
          + '</div>';
      }).join('');

      var faq = $('#bnFaq');
      if (faq) {
        faq.innerHTML = FAQ.map(function (f) {
          return '<div class="bn-faq-row">'
            + '<button class="bn-faq-q" type="button" aria-expanded="false">' + esc(f.q)
            + '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></button>'
            + '<div class="bn-faq-a"><p>' + esc(f.a) + '</p></div>'
            + '</div>';
        }).join('');
      }
      on(faq, 'click', function (e) {
        var q = e.target.closest('.bn-faq-q'); if (!q) return;
        var row = q.parentNode;
        var open = row.classList.toggle('open');
        q.setAttribute('aria-expanded', String(open));
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
      };
    }
  };
})();
